-- 申请中心 + 表级授权投影；门户菜单种子（SYS_RESOURCE，与 lakehouse/src/config/nav.js id 对齐）

CREATE TABLE IF NOT EXISTS `sec_auth_grant` (
  `id`             varchar(20)  NOT NULL COMMENT '主键',
  `revision`       int          NOT NULL DEFAULT 1 COMMENT '乐观锁版本',
  `status`         varchar(32)  DEFAULT 'active' COMMENT 'pending/active/expired/revoked/error',
  `ws`             varchar(64)  DEFAULT 'default' COMMENT '工作空间',
  `remark`         varchar(512) DEFAULT NULL COMMENT '备注',
  `ticket_id`      varchar(20)  DEFAULT NULL COMMENT '申请单ID',
  `subject_type`   varchar(16)  NOT NULL COMMENT 'user/group/sa',
  `subject_id`     varchar(64)  NOT NULL COMMENT '主体ID',
  `asset_id`       varchar(20)  DEFAULT NULL COMMENT 'gov_asset.id（门户预览校验）',
  `grav_asset_id`  varchar(20)  DEFAULT NULL COMMENT 'cb_grav_asset_ref.id',
  `privilege`      varchar(64)  NOT NULL COMMENT '权限 SELECT/...',
  `column_mask`    json         DEFAULT NULL COMMENT '列脱敏摘要',
  `row_filter`     varchar(1024) DEFAULT NULL COMMENT '行过滤',
  `grav_policy_id` varchar(128) DEFAULT NULL COMMENT 'Gravitino策略ID；不可投影可空',
  `grav_projected` tinyint(1)   NOT NULL DEFAULT 0 COMMENT '是否已投影到 Grav ACL',
  `effective_at`   datetime     DEFAULT NULL COMMENT '生效时间',
  `expires_at`     datetime     DEFAULT NULL COMMENT '过期时间',
  `delete_flag`    varchar(32)  DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `create_time`    datetime     DEFAULT NULL COMMENT '创建时间',
  `create_user`    varchar(20)  DEFAULT NULL COMMENT '创建用户',
  `update_time`    datetime     DEFAULT NULL COMMENT '修改时间',
  `update_user`    varchar(20)  DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_sec_grant_subject` (`subject_type`,`subject_id`,`status`) USING BTREE,
  KEY `idx_sec_grant_asset` (`asset_id`,`status`) USING BTREE,
  KEY `idx_sec_grant_expire` (`expires_at`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='投影：授权；引擎真相在Gravitino';

CREATE TABLE IF NOT EXISTS `apply_ticket` (
  `id`          varchar(20)  NOT NULL COMMENT '主键',
  `revision`    int          NOT NULL DEFAULT 1 COMMENT '乐观锁版本',
  `status`      varchar(32)  DEFAULT 'draft' COMMENT 'draft/pending/approved/rejected/cancelled/expired',
  `ws`          varchar(64)  DEFAULT 'default' COMMENT '工作空间',
  `remark`      varchar(512) DEFAULT NULL COMMENT '备注',
  `ticket_no`   varchar(64)  NOT NULL COMMENT '单号',
  `ticket_type` varchar(64)  NOT NULL COMMENT '类型 table_read/...',
  `title`       varchar(256) NOT NULL COMMENT '标题',
  `applicant`   varchar(64)  NOT NULL COMMENT '申请人用户ID',
  `reason`      varchar(1024) DEFAULT NULL COMMENT '事由',
  `payload`     json         DEFAULT NULL COMMENT '申请内容',
  `approved_by` varchar(64)  DEFAULT NULL COMMENT '审批人',
  `approved_at` datetime     DEFAULT NULL COMMENT '审批时间',
  `expires_at`  datetime     DEFAULT NULL COMMENT '授权到期',
  `delete_flag` varchar(32)  DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `create_time` datetime     DEFAULT NULL COMMENT '创建时间',
  `create_user` varchar(20)  DEFAULT NULL COMMENT '创建用户',
  `update_time` datetime     DEFAULT NULL COMMENT '修改时间',
  `update_user` varchar(20)  DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uq_apply_ticket_no` (`ticket_no`) USING BTREE,
  KEY `idx_apply_ticket_status` (`status`,`create_time`) USING BTREE,
  KEY `idx_apply_ticket_applicant` (`applicant`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='SoT：申请单';

CREATE TABLE IF NOT EXISTS `apply_ticket_item` (
  `id`              varchar(20)  NOT NULL COMMENT '主键',
  `revision`        int          NOT NULL DEFAULT 1 COMMENT '乐观锁版本',
  `ticket_id`       varchar(20)  NOT NULL COMMENT '申请单ID',
  `asset_id`        varchar(20)  DEFAULT NULL COMMENT 'gov_asset.id',
  `grav_asset_id`   varchar(20)  DEFAULT NULL COMMENT '资产指针',
  `om_fqn`          varchar(512) DEFAULT NULL COMMENT 'OM FQN',
  `action`          varchar(64)  NOT NULL COMMENT '动作 SELECT/...',
  `detail`          json         DEFAULT NULL COMMENT '明细',
  `result_grant_id` varchar(20)  DEFAULT NULL COMMENT 'sec_auth_grant.id',
  `delete_flag`     varchar(32)  DEFAULT 'NOT_DELETE' COMMENT '删除标志',
  `create_time`     datetime     DEFAULT NULL COMMENT '创建时间',
  `create_user`     varchar(20)  DEFAULT NULL COMMENT '创建用户',
  `update_time`     datetime     DEFAULT NULL COMMENT '修改时间',
  `update_user`     varchar(20)  DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_apply_item_ticket` (`ticket_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='明细：申请单行';

